# Verify-VolumeMoves.Acl-Permissionsと同じ限定的なAllow統合。root以外へは適用しない。
function Root-AclPermissionsR([string]$Base64){
 $descriptor=[Security.AccessControl.RawSecurityDescriptor]::new([Convert]::FromBase64String($Base64),0)
 $flags=[int]$descriptor.ControlFlags-band(-bnot([int][Security.AccessControl.ControlFlags]::DiscretionaryAclAutoInherited-bor[int][Security.AccessControl.ControlFlags]::DiscretionaryAclAutoInheritRequired))
 $identity=$descriptor.Owner.Value+'|'+$descriptor.Group.Value+'|'+$flags
 $dacl=$descriptor.DiscretionaryAcl
 if($null-eq$dacl){return $identity+'|null-dacl'}
 $allowOnly=!@($dacl|Where-Object {$_.AceType-ne[Security.AccessControl.AceType]::AccessAllowed-or$_-isnot[Security.AccessControl.CommonAce]-or([int]$_.AceFlags-band(-bnot31))-ne0}).Count
 foreach($ace in $dacl){$ace.AceFlags=[Security.AccessControl.AceFlags]([int]$ace.AceFlags-band(-bnot[int][Security.AccessControl.AceFlags]::Inherited))}
 if($allowOnly){$normalized=[Security.AccessControl.DiscretionaryAcl]::new($true,$false,$dacl);$rules=@($normalized|ForEach-Object {'{0}|{1}|{2}|{3}'-f$_.SecurityIdentifier.Value,$_.AccessMask,$_.InheritanceFlags,$_.PropagationFlags}|Sort-Object);return $identity+'|allow|'+($rules-join';')}
 $rules=@($dacl|ForEach-Object {$bytes=[byte[]]::new($_.BinaryLength);$_.GetBinaryForm($bytes,0);[Convert]::ToBase64String($bytes)})
 return $identity+'|ordered|'+($rules-join';')
}
$utf8=[Text.UTF8Encoding]::new($false)
# Windowsの標準復元で変わる継承状態だけを除く。ACE順序・適用範囲・権利・Pflagは保持する。
function Inheritance-AclR([string]$Base64){$descriptor=[Security.AccessControl.RawSecurityDescriptor]::new([Convert]::FromBase64String($Base64),0);$mask=[int][Security.AccessControl.ControlFlags]::DiscretionaryAclAutoInherited-bor[int][Security.AccessControl.ControlFlags]::DiscretionaryAclAutoInheritRequired;$descriptor.SetFlags([Security.AccessControl.ControlFlags]([int]$descriptor.ControlFlags-band(-bnot$mask)));if($descriptor.DiscretionaryAcl){foreach($ace in $descriptor.DiscretionaryAcl){$ace.AceFlags=[Security.AccessControl.AceFlags]([int]$ace.AceFlags-band(-bnot[int][Security.AccessControl.AceFlags]::Inherited))}};return $descriptor.GetSddlForm([Security.AccessControl.AccessControlSections]::All)}
function Assert-R([bool]$Condition,[string]$Message){if(!$Condition){throw $Message}}
function Save-R([string]$Path,$Value){[IO.File]::WriteAllText($Path,(ConvertTo-Json -InputObject $Value -Depth 100),$utf8)}
function Snapshot-R([string]$Path){return ,[Prunlet.RecordlessE2E.FixtureNative]::SnapshotTree($Path)}
function Assert-SnapshotR([string]$Path,$Expected,[switch]$WindowsSecurity,[switch]$WindowsInheritance,[switch]$WindowsManagedBin,[switch]$WindowsManagedRestore){$actual=Snapshot-R $Path;Assert-R ($actual.Count-eq$Expected.Count) 'Native member count changed';$byRelative=[Collections.Generic.Dictionary[string,object]]::new([StringComparer]::Ordinal);foreach($node in $actual){Assert-R ($byRelative.TryAdd($node.Relative,$node)) 'Duplicate native member'};foreach($before in $Expected){Assert-R ($byRelative.ContainsKey($before.Relative)) 'Native member missing';$after=$byRelative[$before.Relative];foreach($field in @('Id','Attributes','Directory','NumberOfLinks','ReparseTag','ReparseBase64')){Assert-R ($before.$field-ceq$after.$field) ('Native '+$field+' changed')};Assert-R (($before.Streams|ConvertTo-Json -Depth 10 -Compress)-ceq($after.Streams|ConvertTo-Json -Depth 10 -Compress)) 'All stream bytes changed';if($WindowsManagedBin-or$WindowsManagedRestore){continue};if($WindowsInheritance){if((Inheritance-AclR $before.SecurityBase64)-cne(Inheritance-AclR $after.SecurityBase64)){$script:observed.securityMismatch=@{path=$Path;relative=$before.Relative;before=$before.SecurityBase64;after=$after.SecurityBase64}};Assert-R ((Inheritance-AclR $before.SecurityBase64)-ceq(Inheritance-AclR $after.SecurityBase64)) 'Windows restored O/G/D rights, order, scope or protection changed';continue};if($WindowsSecurity-and$before.Relative-ceq''){$script:observed.securityComparison=@{before=$before.SecurityBase64;after=$after.SecurityBase64;beforePermissions=(Root-AclPermissionsR $before.SecurityBase64);afterPermissions=(Root-AclPermissionsR $after.SecurityBase64)};Assert-R ((Root-AclPermissionsR $before.SecurityBase64)-ceq(Root-AclPermissionsR $after.SecurityBase64)) 'Windows root O/G/D rights changed beyond inherited-flag/standard-Allow equivalence'}else{if($before.SecurityBase64-cne$after.SecurityBase64){$script:observed.securityMismatch=@{path=$Path;relative=$before.Relative;before=$before.SecurityBase64;after=$after.SecurityBase64}};Assert-R ($before.SecurityBase64-ceq$after.SecurityBase64) 'Native complete O/G/D changed'}};return ,$actual}
function Metadata-R([string]$Root){return @((Get-ChildItem -LiteralPath $Root -Force -Recurse|Sort-Object FullName)|ForEach-Object {$relative=$_.FullName.Substring($Root.Length);$id=[Prunlet.RecordlessE2E.FixtureNative]::Identity($_.FullName);$body=if($_.PSIsContainer){'directory'}else{(Get-FileHash -LiteralPath $_.FullName).Hash};$relative+'|'+$id+'|'+$body})-join"`n"}
function No-FileRecordsR($Scope){$members=@(Get-ChildItem -LiteralPath $Scope.metadata -Force -Recurse|ForEach-Object {$_.FullName.Substring($Scope.metadata.Length+1)});$allowed=@('maintenance.lock')+@($Scope.expectedMetadataMembers);$unexpected=@($members|Where-Object {$_-notin$allowed});Assert-R ($unexpected.Count-eq0) ('File-only operations generated recovery artifacts: '+($unexpected-join','));Assert-R (!(Test-Path -LiteralPath $Scope.store)-and!(Test-Path -LiteralPath ($Scope.store+'.restore'))) 'File-only operation generated a Prunlet payload/stage store'}
function Start-R([string]$Exe,[string]$Config,[string[]]$Arguments,[switch]$Streaming){foreach($s in @($Exe,$Config)+$Arguments){if($s-match'["&|<>^%!\r\n]'){throw 'Unsafe CMD argument; fixture paths must use paths-file'}};$info=[Diagnostics.ProcessStartInfo]::new('cmd.exe');$info.UseShellExecute=$false;$info.CreateNoWindow=$true;$info.RedirectStandardInput=$true;$info.RedirectStandardOutput=$true;$info.RedirectStandardError=$true;$info.StandardOutputEncoding=$utf8;$info.StandardErrorEncoding=$utf8;$info.StandardInputEncoding=$utf8;$info.Arguments='/d /s /c ""'+$Exe+'" --config "'+$Config+'" '+(($Arguments|ForEach-Object {'"'+$_+'"'})-join' ')+'"';$info.Environment['TEMP']=$script:temp;$info.Environment['TMP']=$script:temp;$info.Environment['DOTNET_BUNDLE_EXTRACT_BASE_DIR']=Join-Path $OutputDirectory 'runtime-cache';$p=[Diagnostics.Process]::Start($info);return @{process=$p;stdout=$(if($Streaming){$null}else{$p.StandardOutput.ReadToEndAsync()});stderr=$p.StandardError.ReadToEndAsync();arguments=$Arguments;executable=$Exe;config=$Config}}
function Finish-R($Session,[string]$InputText=''){$p=$Session.process;try{if($InputText){$p.StandardInput.Write($InputText)};$p.StandardInput.Close();if(!$p.WaitForExit(240000)){$p.Kill($true);$p.WaitForExit();throw 'CLI timeout'};$stdout=$Session.stdout.GetAwaiter().GetResult();$stderr=$Session.stderr.GetAwaiter().GetResult();$json=$null;try{$json=$stdout|ConvertFrom-Json -AsHashtable -Depth 100}catch{};$r=@{exitCode=$p.ExitCode;stdout=$stdout;stderr=$stderr;json=$json;arguments=$Session.arguments;config=$Session.config;executable=$Session.executable};$script:commands.Add($r);return $r}finally{if(!$p.HasExited){$p.Kill($true);$p.WaitForExit()};$p.Dispose()}}
function Invoke-R($Scope,[string[]]$Arguments,[string]$InputText='',[string]$Exe=$ExecutablePath){return Finish-R (Start-R $Exe $Scope.config $Arguments) $InputText}
function New-ScopeR([string]$Name){$root=Join-Path $OutputDirectory $Name;$null=[IO.Directory]::CreateDirectory($root);$s=@{root=$root;files=(Join-Path $root 'files');metadata=(Join-Path $root 'metadata');store=(Join-Path $root 'store');config=(Join-Path $root 'config.json')};$null=[IO.Directory]::CreateDirectory($s.files);$null=[IO.Directory]::CreateDirectory($s.metadata);$r=Invoke-R $s @('init','--backup-directory',$s.metadata);Assert-R ($r.exitCode-eq0) 'Fixture init failed';$config=Get-Content $s.config -Raw|ConvertFrom-Json -AsHashtable;$config.volumeRecoveryDirectories=@{'D:\'=$s.store};Save-R $s.config $config;return $s}
function File-R($Scope,[string]$Name,[int]$Length=97){$p=Join-Path $Scope.files $Name;$null=[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($p));$b=[byte[]]::new($Length);for($i=0;$i-lt$Length;$i++){$b[$i]=[byte](($i*17+13)%251)};[IO.File]::WriteAllBytes($p,$b);return $p}
function Delete-R($Scope,[string[]]$Paths,[switch]$Recursive,[switch]$DryRun){$pathFile=Join-Path $Scope.root ('paths-'+[guid]::NewGuid().ToString('N')+'.json');Save-R $pathFile $Paths;$arguments=@('delete');if($Recursive){$arguments+='--recursive'};if($DryRun){$arguments+='--dry-run'};$arguments+=@('--paths-file',$pathFile);return Invoke-R $Scope $arguments}
function Assert-WireR($Response,[string[]]$Paths,[string[]]$Statuses,[bool]$DryRun=$false){Assert-R ($null-ne$Response.json-and!$Response.json.ContainsKey('operationId')) 'Recordless JSON missing or contains operationId';Assert-R ((($Response.json.Keys|Sort-Object)-join',') -ceq 'dryRun,items,warnings') 'Unexpected recordless result fields';Assert-R ($Response.json.dryRun-eq$DryRun-and$Response.json.items.Count-eq$Paths.Count) 'Dry-run or item count mismatch';foreach($i in 0..($Paths.Count-1)){$item=$Response.json.items[$i];Assert-R ($item.path-ceq$Paths[$i]-and$item.status-ceq$Statuses[$i]) 'Input-order/path/status mismatch';Assert-R (@($item.Keys|Where-Object {$_-notin @('path','kind','status','error')}).Count-eq0) 'File result leaked recovery/PIDL/backup metadata'}}
function Before-BinR($Snapshot){return ,@([Prunlet.RecordlessE2E.OwnedBinLocator]::FindIdentity($Snapshot[0].Id)|ForEach-Object Pidl)}
function Restore-WindowsVerbR($Item,[string]$Original,[string]$Scope){
 $destination=[IO.Path]::GetFullPath($Original);$scopePath=[IO.Path]::GetFullPath($Scope).TrimEnd('\')+'\';Assert-R ($destination.StartsWith($scopePath,[StringComparison]::OrdinalIgnoreCase)) 'Windows Restore destination escaped owned scope';Assert-R (!(Test-Path -LiteralPath $destination)) 'Windows Restore destination occupied';$parent=[IO.Path]::GetDirectoryName($destination);Assert-R ([IO.Directory]::Exists($parent)) 'Windows Restore original parent missing';$ancestor=$parent;while($ancestor){Assert-R (!((Get-Item -LiteralPath $ancestor -Force).Attributes-band[IO.FileAttributes]::ReparsePoint)) 'Windows Restore parent traverses link';$ancestor=[IO.Path]::GetDirectoryName($ancestor)}
 Assert-R ([Prunlet.RecordlessE2E.FixtureNative]::Identity($Item.PhysicalPath)-ceq$Item.NativeId) 'Owned recycle native identity changed';$shell=New-Object -ComObject Shell.Application;$folder=$shell.NameSpace(10);$matches=@($folder.Items()|Where-Object {$_.Path-ceq$Item.PhysicalPath});Assert-R ($matches.Count-eq1) 'Exact owned Windows bin FolderItem missing';$owned=$matches[0];Assert-R ([Prunlet.RecordlessE2E.FixtureNative]::Identity($owned.Path)-ceq$Item.NativeId) 'Exact Windows FolderItem identity changed';$verbs=@($owned.Verbs());$restore=@($verbs|Where-Object {$_.Name.Replace('&','')-match'^(元に戻す|Restore)(\([A-Za-z]\))?$'});Assert-R ($restore.Count-eq1) 'Windows Restore verb missing or ambiguous';$restore[0].DoIt();$clock=[Diagnostics.Stopwatch]::StartNew();while(!(Test-Path -LiteralPath $destination)-and$clock.ElapsedMilliseconds-lt30000){[Threading.Thread]::Sleep(50)};Assert-R ((Test-Path -LiteralPath $destination)-and!(Test-Path -LiteralPath $Item.PhysicalPath)) 'Windows Restore verb did not restore original path';Assert-R ([Prunlet.RecordlessE2E.FixtureNative]::Identity($destination)-ceq$Item.NativeId) 'Windows Restore original native identity changed';$script:observed.restoreRoute=@{method='exact owned FolderItem Restore verb';destination=$destination;verb=$restore[0].Name};return $destination
}
function Restore-BinR($Scope,[string]$Original,$Before,[string[]]$Prior){$item=[Prunlet.RecordlessE2E.OwnedBinLocator]::FindNew($Before[0].Id,$Prior);$bin=Assert-SnapshotR $item.PhysicalPath $Before -WindowsManagedBin;$script:observed.bin=@{item=$item;before=$Before;bin=$bin};$null=Restore-WindowsVerbR $item $Original $Scope.root;$after=Assert-SnapshotR $Original $Before -WindowsInheritance;$script:observed.restored=$after;$afterByRelative=[Collections.Generic.Dictionary[string,object]]::new([StringComparer]::Ordinal);foreach($node in $after){$afterByRelative.Add($node.Relative,$node)};$script:observed.externalShellSecurityDiff=@($Before|ForEach-Object {$old=$_;$new=$afterByRelative[$old.Relative];@{relative=$old.Relative;before=$old.SecurityBase64;after=$new.SecurityBase64;equal=($old.SecurityBase64-ceq$new.SecurityBase64)}});No-FileRecordsR $Scope;return ,$after}function Open-McpR($Scope){$session=Start-R $ExecutablePath $Scope.config @('mcp') -Streaming;$session.transcript=[Collections.Generic.List[object]]::new();$script:observed.mcp=$session.transcript;return $session}
function Rpc-R($Session,$Request){$line=$Request|ConvertTo-Json -Depth 30 -Compress;$Session.transcript.Add(@{sent=$Request});$Session.process.StandardInput.WriteLine($line);$Session.process.StandardInput.Flush();if(!$Request.ContainsKey('id')){return};foreach($attempt in 1..256){$read=$Session.process.StandardOutput.ReadLineAsync();if(!$read.Wait(30000)){throw 'MCP response timeout'};$raw=$read.GetAwaiter().GetResult();if($null-eq$raw){throw 'MCP EOF before response'};$response=$raw|ConvertFrom-Json -AsHashtable -Depth 100;$Session.transcript.Add(@{received=$response});if($response.ContainsKey('id')-and$response.id-eq$Request.id){return $response}};throw 'MCP notification bound exceeded'}
function Init-McpR($Session){$r=Rpc-R $Session @{jsonrpc='2.0';id=1;method='initialize';params=@{protocolVersion='2024-11-05';capabilities=@{};clientInfo=@{name='recordless-e2e';version='1'}}};Assert-R (!$r.error) 'MCP initialize failed';$null=Rpc-R $Session @{jsonrpc='2.0';method='notifications/initialized'}}
function Call-McpR($Session,[int]$Id,[string]$Tool,$Arguments){$r=Rpc-R $Session @{jsonrpc='2.0';id=$Id;method='tools/call';params=@{name=$Tool;arguments=$Arguments}};if($r.error-or$r.result.isError){return @{failed=$true;response=$r}};Assert-R ($r.result.content.Count-eq1-and$r.result.content[0].type-ceq'text') 'Unexpected MCP tool result';return @{failed=$false;response=$r;json=($r.result.content[0].text|ConvertFrom-Json -AsHashtable -Depth 100)}}
function Close-McpR($Session){try{$Session.process.StandardInput.Close();if(!$Session.process.WaitForExit(30000)){$Session.process.Kill($true);$Session.process.WaitForExit();throw 'MCP shutdown timeout'};$script:observed.mcpExitCode=$Session.process.ExitCode;$script:observed.mcpStderr=$Session.stderr.GetAwaiter().GetResult();Assert-R ($Session.process.ExitCode-eq0) 'MCP process exit nonzero'}finally{if(!$Session.process.HasExited){$Session.process.Kill($true);$Session.process.WaitForExit()};$Session.process.Dispose()}}function Roundtrip-BatchR($Scope,[string[]]$Paths,[switch]$Recursive){$proofs=@($Paths|ForEach-Object {, (Snapshot-R $_)});$prior=@($proofs|ForEach-Object {, (Before-BinR $_)});$r=Delete-R $Scope $Paths -Recursive:$Recursive;Assert-WireR $r $Paths (@($Paths|ForEach-Object {'recycled'}));Assert-R ($r.exitCode-eq0) 'Batch recycling failed';foreach($i in 0..($Paths.Count-1)){$null=Restore-BinR $Scope $Paths[$i] $proofs[$i] $prior[$i]};foreach($i in 0..($Paths.Count-1)){$null=Assert-SnapshotR $Paths[$i] $proofs[$i] -WindowsInheritance};$script:observed.batch=@{paths=$Paths;before=$proofs;restoredAll=$true};No-FileRecordsR $Scope}
